package com.codeguardian.service.rag; import org.springframework.stereotype.Service; import java.util.*; @Service public class EmbeddingService{public float[] embed(String text){float[] v=new float[384];if(text==null)return v;for(String token:text.toLowerCase().split("[^a-z0-9_]+")){if(!token.isBlank())v[Math.floorMod(token.hashCode(),v.length)]+=1f;}float sum=0;for(float n:v)sum+=n*n;float norm=(float)Math.sqrt(sum);if(norm>0)for(int i=0;i<v.length;i++)v[i]/=norm;return v;}public String asPgVector(float[] v){StringBuilder s=new StringBuilder("[");for(int i=0;i<v.length;i++){if(i>0)s.append(',');s.append(v[i]);}return s.append(']').toString();}}
